{
  "interpretation": {
    "name": "TightenForkliftLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2, tighten the fasteners of variant F30 using the MES program, send the tool back to the crib immediately after tightening, and evaluate and record the result while the tool travels.",
    "constraints": [
      "NR7 must be reserved before use and released after its return transport (E1, E6).",
      "NR7 must be at the station before configure-tool and tighten-fasteners (E3).",
      "The tightening program comes only from get-program; no numeric process values appear in the Recipe (E4).",
      "Both transport-tool Steps are delegated to agvexecutor (E2).",
      "Every tool-using Step depends on reserve-tool so that it renews the lease (E6).",
      "The tightening must be evaluated and recorded (E5).",
      "The return transport starts right after tighten-fasteners; evaluate-tightening and record-tightening run in parallel with it."
    ],
    "preference": "Free the shared tool as early as possible for other lines.",
    "priority": "normal",
    "horizon": "Single execution for the current request.",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-tighten-and-return-tool",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "finish",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-fasteners"],
            "dep": ["program", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
